package mx.ita.menu_desplegable.ui.theme.screens

import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.navigation3.runtime.NavEntry
import mx.ita.menu_desplegable.ui.theme.screens.home.Home

@Composable
fun Navigation(modifier: Modifier = Modifier) {
    val backStack = remember { mutableSetOf<Any>(Home) }

    NavDisplay(
        backStack = backStack,
    ) { key ->
        when (key) {
            Home -> NavEntry(key) {
                Home()
            }
            else -> NavEntry(Unit){
                Text(text = "Unknown")
            }
        }

    }

}

