@Serializable
data object Home

data class Product(
    val id: Int,
    val name: String,
    val price: Double,
    val description: String,
)

val sampleProducts = listOf(
    Product(1, "Smartphone Pro", 999.99, "Teléfono inteligente con cámara de alta resolución."),
    Product(2, "Laptop Ultra", 1299.50, "Computadora portátil potente para trabajo y desarrollo."),
    Product(3, "Audífonos Inalámbricos", 149.99, "Audífonos con cancelación de ruido activa."),
    Product(4, "Reloj Inteligente", 199.99, "Monitoreo de salud y notificaciones al instante."),
    Product(5, "Teclado Mecánico", 89.90, "Teclado RGB con switches táctiles de alta precisión.")
)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun Home(
    onProductClick: (Product) -> Unit = {},
) {
    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(text = "Lista de Productos") }
            )
        }
    ) { innerPadding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding),
            contentPadding = PaddingValues(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            items(sampleProducts) { product ->
                ProductItem(
                    product = product,
                    onClick = { onProductClick(product) },
                )
            }
        }
    }
}

@Composable
fun ProductItem(
    product: Product,
    onClick: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() },
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = product.name,
                    style = MaterialTheme.typography.titleMedium
                )
                Text(
                    text = "$${product.price}",
                    style = MaterialTheme.typography.titleSmall,
                    color = MaterialTheme.colorScheme.primary
                )
            }
            Spacer(modifier = Modifier.height(6.dp))
            Text(
                text = product.description,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
    }
}

